-- Orava Certificate Store · 0005 · labs with logos, report categories, Replace instead of copies
-- Run with `pnpm db:migrate`. Deny-all Row Level Security like every other table.

-- ── Labs: the laboratory that issued a certificate, with its logo ─────────────────────────────
create table if not exists labs (
  id               uuid primary key default gen_random_uuid(),
  slug             text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name             text not null,                    -- full name, e.g. Asian Institute of Gemological Sciences
  short_name       text not null,                    -- used in type names and file names, e.g. AIGS
  website          text not null default '',
  logo             bytea,                            -- small image, checked on upload (max 512 KB)
  logo_mime        text check (logo_mime in ('image/png', 'image/jpeg', 'image/webp')),
  logo_updated_at  timestamptz,
  archived         boolean not null default false,
  sort_order       integer not null default 0,
  created_by       uuid references app_users (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  check (octet_length(logo) <= 524288),
  check ((logo is null) = (logo_mime is null))
);

do $$
begin
  execute 'alter table labs enable row level security';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on table labs from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on table labs from authenticated';
  end if;
end $$;

insert into labs (slug, name, short_name, website, logo, logo_mime, logo_updated_at, sort_order)
values
  ('aigs', 'Asian Institute of Gemological Sciences', 'AIGS', 'https://www.aigsthailand.com',
   decode('', 'base64'), 'image/webp', now(), 0),
  ('bellerophon', 'Bellerophon Gemlab', 'Bellerophon', 'https://bellerophongemlab.com',
   decode('', 'base64'), 'image/webp', now(), 1)
on conflict (slug) do nothing;

-- ── Types: which lab, and which kind of report ────────────────────────────────────────────────
alter table certificate_types add column if not exists lab_id uuid references labs (id);
alter table certificate_types add column if not exists category text
  check (category in ('individual', 'lot'));

-- Any other lab already typed on a type becomes a lab of its own
insert into labs (slug, name, short_name, sort_order)
select distinct on (s.slug) s.slug, s.lab, s.lab, 10
from (
  select lab, trim(both '-' from regexp_replace(lower(lab), '[^a-z0-9]+', '-', 'g')) as slug
  from certificate_types where trim(lab) <> ''
) s
where s.slug <> '' and not exists (
  select 1 from labs l where l.slug = s.slug or lower(l.short_name) = lower(s.lab)
)
on conflict (slug) do nothing;

update certificate_types t set lab_id = l.id
from labs l
where t.lab_id is null and trim(t.lab) <> ''
  and (lower(l.short_name) = lower(trim(t.lab)) or lower(l.name) = lower(trim(t.lab)));

-- The old free-text lab column now just mirrors the lab's short name
update certificate_types t set lab = l.short_name from labs l where t.lab_id = l.id;

-- The 4 sample types get the company's names. A type the admin already renamed keeps its name.
update certificate_types set category = 'individual', name = 'AIGS Individual Gem Stone Report'
where slug = 'aigs-gemstone-identification-report' and name = 'AIGS Gemstone Identification Report';
update certificate_types set category = 'lot', name = 'AIGS Lot Wise Gem Stones Report'
where slug = 'aigs-analysis-short-report' and name = 'AIGS Analysis Short Report';
update certificate_types set category = 'individual', name = 'Bellerophon Individual Gem Stone Report'
where slug = 'bellerophon-gemmological-report' and name = 'Bellerophon Gemmological Report';
update certificate_types set category = 'lot', name = 'Bellerophon Lot Wise Gem Stones Report'
where slug = 'bellerophon-gemmological-testing-results' and name = 'Bellerophon Gemmological Testing Results';

update certificate_types set category = 'individual'
where category is null and slug in ('aigs-gemstone-identification-report', 'bellerophon-gemmological-report');
update certificate_types set category = 'lot'
where category is null and slug in ('aigs-analysis-short-report', 'bellerophon-gemmological-testing-results');

-- ── Certificates: one live certificate per report number; a replaced one is kept as history ──
alter table certificates add column if not exists replaced_by uuid references certificates (id);
alter table certificates add column if not exists replaced_at timestamptz;
create index if not exists certificates_replaced_by_idx on certificates (replaced_by)
  where replaced_by is not null;

-- Copies saved before this change: the newest stays, older ones become its history (restorable)
with ranked as (
  select id, type_id, lower(report_no) as rn,
    first_value(id) over (partition by type_id, lower(report_no) order by created_at desc, id desc) as keep
  from certificates
  where deleted_at is null and report_no is not null and report_no <> ''
)
update certificates c
set deleted_at = now(), replaced_by = r.keep, replaced_at = now(), updated_at = now()
from ranked r
where c.id = r.id and r.id <> r.keep;

create unique index if not exists certificates_type_report_no_key
  on certificates (type_id, lower(report_no))
  where deleted_at is null and report_no is not null and report_no <> '';
